.d-raster-dot-matrix-shapes-label{color:#9b9ba3}.d-raster-dot-matrix-shapes-speed{text-align:right}
.d-raster-dot-matrix-shapes-stage{position:absolute;inset:38px 8px 74px;display:grid;place-items:center;box-sizing:border-box;overflow:hidden;border:1px solid #232327;border-radius:10px;background:radial-gradient(circle at 50% 48%,#101012 0,#0a0a0b 72%);touch-action:none}
