.d-raster-dot-matrix-shapes-controls{position:absolute;left:12px;right:12px;bottom:18px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}
.d-raster-dot-matrix-shapes-chip{min-width:0;height:34px;box-sizing:border-box;overflow:hidden;padding:0 5px;border:1px solid #232327;border-radius:999px;background:#161619;color:#5c5c66;font:10px/1 'JetBrains Mono',monospace;letter-spacing:.02em;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}
.d-raster-dot-matrix-shapes-chip[aria-checked="true"]{border-color:#2e2e34;color:#fa7319}.d-raster-dot-matrix-shapes-chip:hover{color:#9b9ba3}.d-raster-dot-matrix-shapes-chip[aria-checked="true"]:hover{color:#fa7319}.d-raster-dot-matrix-shapes-chip:focus-visible{outline:1px solid #fa7319;outline-offset:2px}
.d-raster-dot-matrix-shapes-status{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
@container(max-width:340px){.d-raster-dot-matrix-shapes-head{left:12px;right:12px}.d-raster-dot-matrix-shapes-stage{left:6px;right:6px}.d-raster-dot-matrix-shapes-controls{left:8px;right:8px;gap:3px}.d-raster-dot-matrix-shapes-chip{padding:0 3px}}
